fn main(){let out=Path::new(O);fs::copy(format!("{R}/report-draft.md"),out.join("README.md")).unwrap();for f in["history-correction.md","update-publication.rs"]{fs::copy(format!("{R}/{f}"),out.join("artifacts").join(f)).unwrap();}let old=Path::new("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-11-05-g2-fixed-odd-screen176");let provenance=json!({"already_closed_family":true,"prior_report":"../2026-11-05-g2-fixed-odd-screen176/README.md","prior_report_sha256":hash(&fs::read(old.join("README.md")).unwrap()),"prior_analysis_sha256":hash(&fs::read(old.join("artifacts/analysis.json")).unwrap()),"prior_reference":serde_json::from_slice::<Value>(&fs::read(old.join("artifacts/prior-art.json")).unwrap()).unwrap(),"current_work_scope":"follow-up indexed-top/Booth/grouped2x2 audit;notnewoptimizationlead","history_mistake_disclosed_before_commit":true});fs::write(out.join("artifacts/history-provenance.json"),serde_json::to_vec_pretty(&provenance).unwrap()).unwrap();let p=out.join("artifacts/publication.json");let mut meta:Value=serde_json::from_slice(&fs::read(&p).unwrap()).unwrap();meta["postpublication_history_correction_added_before_commit"]=json!(true);meta["frozen_inputs_helpers_and_receipt_archive_unchanged"]=json!(true);fs::write(p,serde_json::to_vec_pretty(&meta).unwrap()).unwrap();let mut sums=String::new();let mut n=0;for p in walk(out){if p.file_name().unwrap()=="SHA256SUMS"{continue;}writeln!(sums,"{}  {}",hash(&fs::read(&p).unwrap()),p.strip_prefix(out).unwrap().display()).unwrap();n+=1;}fs::write(out.join("SHA256SUMS"),sums).unwrap();println!("Updated{n}members+checksum; priornegativeandhistorymistakeexplicit; no count/test/capture rerun.");}
